class CallHookTest {
    private val info = CallInfo("getItem", "GET", "/items/{id}", "http://localhost/items/7", "localhost")

    private fun recording(
        name: String,
        log: MutableList<String>,
    ): CallHook =
        CallHook { _, _ ->
            log.add("start $name")
            CallObserver { log.add("finish $name") }
        }

    @Test
    @DisplayName(
        "bhvHooks020 chain starts the hooks in order and finishes their observers in reverse order, and a hook that returns nothing is skipped",
    )
    fun chainOrdersStartAndFinish() {
        val log = mutableListOf<String>()
        val silent =
            CallHook { _, _ ->
                log.add("start silent")
                null
            }

        val chained = CallHook.chain(recording("a", log), silent, recording("b", log))
        val observer = chained.start(info, mutableMapOf())
        observer!!.finish(CallOutcome(200, emptyMap(), null))

        assertEquals(listOf("start a", "start silent", "start b", "finish b", "finish a"), log)
        assertNull(CallHook.chain(silent).start(info, mutableMapOf()))
    }

    @Test
    @DisplayName("bhvLangkotlin010 a failing observer in a chain does not stop the others from finishing")
    fun bhvLangkotlin010AFailingObserverDoesNotStopTheChain() {
        val log = mutableListOf<String>()
        val failing = CallHook { _, _ -> CallObserver { throw IllegalStateException("observer") } }

        CallHook
            .chain(recording("a", log), failing)
            .start(info, mutableMapOf())!!
            .finish(CallOutcome(0, null, null))

        assertEquals(listOf("start a", "finish a"), log)
    }

    @Test
    @DisplayName("bhvLangkotlin011 every hook of a chain sees the edits of the hooks before it")
    fun bhvLangkotlin011HooksSeeTheEditsBeforeThem() {
        val first =
            CallHook { _, headers ->
                headers["X-Step"] = "one"
                null
            }
        var seen: String? = null
        val second =
            CallHook { _, headers ->
                seen = headers["X-Step"]
                null
            }

        CallHook.chain(first, second).start(info, mutableMapOf())

        assertEquals("one", seen)
    }
}
